content.content:
export type FieldType = 'string' | 'number';
export type Field = { name: string; type: FieldType; required: boolean };

export type Widget = 'alerts' | 'result' | 'score';

/** Every widget, in sidebar order. One overlay token serves them all; a
 *  `?w=<id>` on the overlay URL narrows a Browser Source to a single widget,
 *  so OBS can place the alert corner and the full-screen result in separate
 *  sources. No `w` renders everything (the pre-widget-URL behaviour). */
export const WIDGETS: readonly { id: Widget; label: string; href: string }[] = [
  { id: 'alerts', label: 'Alerts', href: '/dashboard/w/alerts' },
  { id: 'result', label: 'Win / Loss', href: '/dashboard/w/win-loss' },
  { id: 'score', label: 'Scoreboard', href: '/dashboard/w/score' },
];

/** Narrows an untrusted `?w=` value to a Widget, or null for "all widgets". */
export function parseWidget(v: unknown): Widget | null {
  return WIDGETS.some((w) => w.id === v) ? (v as Widget) : null;
}
export type Preset = 'confetti' | 'slam' | 'glitch';
export const PRESETS: readonly Preset[] = ['confetti', 'slam', 'glitch'];

export type Style = {
  accent: string;
  bg: string;
  fg: string;
  font: string;
  size: number;
  pos: string;
  width: number;
  radius: number;
  anim: 'fade' | 'slide' | 'pop';
  // Only read by the result widget's full-screen renderer; the alert card
  // ignores it. Lives in the existing Json `style` column, so adding it needs
  // no migration.
  preset: Preset;
};

export type ConfigDefaults = {
  template: string;
  titleTemplate: string;
  style: Style;
  durationMs: number;
};

export const BASE_STYLE: Style = {
  accent: '#7c5cff',
  bg: 'rgba(12,12,16,0.86)',
  fg: '#ffffff',
  font: 'system-ui, sans-serif',
  size: 34,
  pos: 'top',
  width: 640,
  radius: 16,
  anim: 'fade',
  preset: 'slam',
};

const s = (name: string, required = false): Field => ({ name, type: 'string', required });
const n = (name: string, required = false): Field => ({ name, type: 'number', required });

export const BUILT_IN: Record<
  string,
  { label: string; widget: Widget; fields: Field[]; defaults: ConfigDefaults }
> = {
  donation: {
    label: 'Donation',
    widget: 'alerts',
    fields: [s('name', true), n('amount', true), s('currency'), s('message')],
    defaults: {
